<script setup lang="ts">
import {canAccess} from '../../shared/modules';
import {confirmAction} from '../lib/dialog';
import {ref,computed,watch,onMounted} from 'vue';
import EventPicker from '../components/EventPicker.vue';
import FileDropzone from '../components/FileDropzone.vue';
import {api,catalog,session,displayTime,loadCatalog} from '../lib/api';
import {MAX_WISH_AUDIO_SIZE,type Wish,type WishList} from '../../shared/wishes';
const hasSubmitted=ref(false);
const items=ref<Wish[]>([]),page=ref(1),total=ref(0),ready=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),progress=ref('');
const name=ref(''),text=ref(''),file=ref<File|null>(null),draftId=ref(''),version=ref(1),audioName=ref(''),audioVersion=ref(''),removeId=ref(''),createId=ref(crypto.randomUUID()),submitId=ref(crypto.randomUUID()),lastPayload=ref('');
const admin=computed(()=>canAccess(session.user,'wishes')),event=computed(()=>catalog.events.find(e=>e.id===catalog.eventId));
const storageKey=()=>`usagi-wish:${session.user?.id}:${catalog.eventId}`;
function backup(){try{localStorage.setItem(storageKey(),JSON.stringify({name:name.value,text:text.value,draftId:draftId.value,version:version.value,createId:createId.value,submitId:submitId.value,lastPayload:lastPayload.value,audioName:audioName.value,audioVersion:audioVersion.value,removeId:removeId.value}));}catch{/* Inputs remain available even if local storage is denied. */}}
function restore(){reset(false);try{const saved=JSON.parse(localStorage.getItem(storageKey())??'null');if(saved){name.value=saved.name??'';text.value=saved.text??'';draftId.value=saved.draftId??'';version.value=saved.version??1;createId.value=saved.createId??crypto.randomUUID();submitId.value=saved.submitId??crypto.randomUUID();lastPayload.value=saved.lastPayload??'';audioName.value=saved.audioName??'';audioVersion.value=saved.audioVersion??'';removeId.value=saved.removeId??'';}}catch{/* Ignore malformed optional local backup. */}}
function reset(remove=true){if(remove)localStorage.removeItem(storageKey());name.value=session.user?.nickname??'';text.value='';file.value=null;draftId.value='';audioName.value='';audioVersion.value='';removeId.value='';version.value=1;createId.value=crypto.randomUUID();submitId.value=crypto.randomUUID();lastPayload.value='';}
let loadSequence=0;
async function load(){const sequence=++loadSequence,eventId=catalog.eventId;if(!eventId)return;loading.value=true;try{const data=await api<WishList>(`/api/wishes?event_id=${encodeURIComponent(eventId)}&page=${page.value}`);if(sequence!==loadSequence)return;items.value=data.items;total.value=data.total;ready.value=data.audio_ready;hasSubmitted.value=data.has_submitted;const existing=data.items.find(w=>w.status==='draft');if(!hasSubmitted.value&&!draftId.value&&existing){draftId.value=existing.id;version.value=existing.version;audioName.value=existing.filename??'';audioVersion.value=existing.audio_version??'';if(!name.value)name.value=existing.display_name==='未署名'?(session.user?.nickname??''):existing.display_name;if(!text.value)text.value=existing.text;backup();}}catch(e){if(sequence===loadSequence)error.value=(e as Error).message;}finally{if(sequence===loadSequence)loading.value=false;}}
function pickFile(selected:File){if(busy.value||!ready.value||!admin.value||audioName.value)return;error.value='';if(!selected.size||selected.size>MAX_WISH_AUDIO_SIZE){error.value='请选择不超过 20 MB 的音频文件';return;}file.value=selected;}
function resume(wish:Wish){if(draftId.value===wish.id){audioName.value=wish.filename??audioName.value;audioVersion.value=wish.audio_version??'';notice.value='草稿内容已保留，可以继续投稿';return;}name.value=wish.display_name==='未署名'?'':wish.display_name;text.value=wish.text;draftId.value=wish.id;version.value=wish.version;audioName.value=wish.filename??'';audioVersion.value=wish.audio_version??'';removeId.value='';file.value=null;notice.value='已恢复草稿，可以继续填写并提交';backup();}
async function submit(){error.value='';notice.value='';if(hasSubmitted.value){error.value='每个账号在同一活动只能投稿一则祝福语';return;}if(!name.value.trim()){error.value='请填写署名';return;}if(!text.value.trim()){error.value='请填写祝福语文本';return;}
 busy.value=true;const eventId=catalog.eventId;try{progress.value='正在准备投稿…';if(!draftId.value){const draft=await api<{id:string;version:number}>('/api/wishes',{event_id:eventId,operation_id:createId.value});draftId.value=draft.id;version.value=draft.version;backup();}
 if(file.value){progress.value='正在上传语音，请保留此页面…';const response=await fetch('/api/wishes/'+draftId.value+'/audio',{method:'PUT',headers:{'X-Requested-With':'usagi','X-Filename':encodeURIComponent(file.value.name)},body:file.value,signal:AbortSignal.timeout(120000)});if(!response.ok){const result=await response.json() as {error?:string};throw new Error(result.error??'语音上传失败');}const result=await response.json() as {audio_version:string};audioVersion.value=result.audio_version;audioName.value=file.value.name;file.value=null;backup();}
 progress.value='正在提交祝福语…';const payload={display_name:name.value.trim(),text:text.value.trim(),expectedVersion:version.value};const serialized=JSON.stringify(payload);if(lastPayload.value&&lastPayload.value!==serialized)submitId.value=crypto.randomUUID();lastPayload.value=serialized;backup();await api('/api/wishes/'+draftId.value+'/submit',{...payload,operation_id:submitId.value});reset();notice.value='祝福语已提交。';page.value=1;await load();}catch(e){error.value=(e as Error).message;backup();}finally{busy.value=false;progress.value='';}}
watch([name,text],()=>{if(!busy.value)backup();});
watch(()=>catalog.eventId,()=>{page.value=1;error.value='';notice.value='';restore();void load();});watch(page,()=>void load());
onMounted(async()=>{try{if(!catalog.config)await loadCatalog();restore();await load();}catch(e){error.value=(e as Error).message;}});

async function removeAudio(){if(busy.value||!draftId.value||!await confirmAction('移除这份草稿的已上传音频？之后可以重新选择文件。'))return;busy.value=true;error.value='';try{if(!audioVersion.value){const data=await api<WishList>(`/api/wishes?event_id=${encodeURIComponent(catalog.eventId)}&page=1`);audioVersion.value=data.items.find(w=>w.id===draftId.value)?.audio_version??'';}if(!audioVersion.value)throw new Error('请从“我的祝福语”继续此草稿，刷新音频状态后重试。');if(!removeId.value)removeId.value=crypto.randomUUID();backup();await api('/api/wishes/'+draftId.value+'/audio',{expectedVersion:version.value,expectedAudio:audioVersion.value,operation_id:removeId.value},'DELETE');removeId.value='';audioName.value='';audioVersion.value='';file.value=null;backup();notice.value='音频已移除，可以选择新的文件。';await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><div class="page wishes-page"><header class="page-head"><div><h1>祝福语投稿</h1></div><EventPicker :disabled="busy"/></header><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><div class="wish-layout"><section v-if="!hasSubmitted" class="paper wish-form"><h2>填写祝福语</h2><p class="hint">每个账号在同一活动只能投稿一则，已有草稿可继续填写。</p><p class="hint">祝福语仅本人和活动管理员可见，提交后由管理员收集使用。</p><p v-if="event&&!event.wishes_open&&!admin" class="alert warning">本活动暂未开放祝福语投稿。已填写的内容会保留。</p><form id="wish-submit-form" @submit.prevent="submit"><fieldset :disabled="busy||loading"><FieldLabel>署名 <input v-model="name" required maxlength="80" autocomplete="nickname" placeholder="希望展示的名字"></FieldLabel><FieldLabel>祝福语（必填） <textarea v-model="text" required maxlength="2000" rows="7" placeholder="请输入祝福语"></textarea><span class="hint counter">{{ text.length }} / 2000</span></FieldLabel><section v-if="admin" class="audio-upload"><h3>语音祝福 <span class="hint">管理员专属 · 可选</span></h3><p class="hint">祝福语文本必填，语音为可选附件。支持 MP3、WAV、M4A、OGG、FLAC、WebM，每份不超过 20 MB。</p><p v-if="!ready" class="alert warning">语音上传尚未开放，请先保留本地录音；文本仍可正常投稿。</p><div v-if="audioName"><p class="hint">已上传：{{ audioName }}。提交时会一并收录。</p><button type="button" :disabled="busy" @click="removeAudio">移除音频 / 重新选择</button></div><FileDropzone v-else label="选择音频" hint="选择或拖入一个音频文件，点击「提交祝福语」后上传。" accept="audio/*,.mp3,.wav,.m4a,.ogg,.flac,.webm" :disabled="!ready||busy" @selected="pickFile"/><p v-if="file" class="hint">{{ file.name }} · {{ (file.size/1024/1024).toFixed(2) }} MB</p></section><p v-else class="hint">普通账号支持文本祝福语。</p><PageActions :status="busy?progress:undefined"><button class="primary" type="submit" form="wish-submit-form" :disabled="busy||loading||!event||(!event.wishes_open&&!admin)">{{ busy?'提交中…':'提交祝福语' }}</button></PageActions></fieldset><p v-if="busy" role="status" class="hint">{{ progress }}</p></form></section><section v-else class="paper wish-form"><h2>本活动的祝福语已提交</h2><p>每个账号在同一活动只能投稿一则。你可以在「我的祝福语」中查看已提交的内容。</p></section><section class="paper own-wishes"><div class="inline"><h2>我的祝福语</h2><span class="hint">{{ total }} 份</span></div><p v-if="loading" role="status" class="hint">正在读取…</p><p v-else-if="!items.length" class="empty">暂无祝福语。</p><article v-for="wish in items" :key="wish.id"><div class="inline"><strong>{{ wish.display_name }}</strong><span class="wish-state">{{ wish.status==='submitted'?'已提交':'未提交草稿' }}</span></div><p class="prewrap">{{ wish.text||'（未填写祝福语文本）' }}</p><audio v-if="wish.filename" controls preload="none" :src="'/api/wishes/'+wish.id+'/audio'" :aria-label="wish.display_name+'的祝福语音'"></audio><p class="hint">{{ displayTime(wish.submitted_at??wish.created_at,event?.timezone) }}</p><button v-if="wish.status==='draft'" :disabled="busy" @click="resume(wish)">继续投稿</button></article><div v-if="total>30" class="pagination"><button :disabled="page===1||loading" @click="page--">上一页</button><span>{{ page }}</span><button :disabled="page*30>=total||loading" @click="page++">下一页</button></div><RouterLink v-if="admin" to="/admin/wishes" class="text-button">查看全部祝福语 →</RouterLink></section></div></div></template>
<style scoped>
.wish-layout{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:24px;align-items:start}fieldset{border:0;padding:0;margin:0;min-width:0}.wish-form h2,.own-wishes h2{font-size:22px}.counter{text-align:right}.audio-upload{padding:20px 0;border-top:1px solid var(--line);margin-bottom:16px}.audio-upload h3{font-size:16px}.own-wishes article{padding:20px 0;border-bottom:1px solid var(--line)}.own-wishes article:last-of-type{border-bottom:0}.wish-state{font-size:12px;color:var(--muted);margin-left:auto}audio{width:100%;margin:12px 0}.prewrap{overflow-wrap:anywhere}@media(max-width:900px){.wish-layout{grid-template-columns:minmax(0,1fr)}}
</style>
